export interface HelpSection { title: string; paragraphs: string[]; bullets?: string[]; example?: string }
export interface HelpTopic { id: string; category: string; title: string; summary: string; sections: HelpSection[]; related: string[] }
export const HELP_TOPICS: HelpTopic[] = [
  { id: 'productivity', category: 'Workflow & troubleshooting', title: 'Recovery, search, templates, budgets, and delivery', summary: 'Professional workflows stay in dedicated views and expandable controls.', sections: [
    { title: 'Recover and retain context', paragraphs: ['Workflow center → Recovery reviews failed runs, checks the selected account and folder, and offers setup guidance and an explicit retry. It does not infer a precise cause from exit code 1 alone.', 'Rename a channel in its Settings, beside its budget alerts. Native IDs are retained when structured telemetry identifies the conversation, so the channel can resume after a restart. Duplicate makes a fresh conversation; Start a fresh conversation next time clears the resume reference without deleting provider history.', 'Name and pin native conversations from Session history. Prepared coaching requests persist until delivered, and are never sent automatically. Start the channel, handle CLI trust prompts, and explicitly send the request.'] },
    { title: 'Search and reuse setup', paragraphs: ['Ctrl+Shift+F (Cmd+Shift+F on a Mac) opens local search for source files, curated notes, and rules. Recorded output is opt-in because it can contain private text. Known credentials, dependency/build folders, and symlink escapes are skipped. The bounded scan reports when limits are reached.', 'Templates preserve layouts, raw model parameters, budgets, optional rules, and verification profiles. Resume IDs, prepared requests, credentials, and check results are excluded. Applying requires stopped channels and native review, creates new channels, binds them to the selected project, and never launches commands automatically. Replacing canonical rules may require reapplying them to other projects.'] },
    { title: 'Review, iterate, and ship', paragraphs: ['Changes → Delivery lets you review selected paths, commit all staged changes, push a named branch without force, and create a pull request through local gh. Every write/remote action requires confirmation; changed repository fingerprints invalidate review. Git hooks execute local code. Inspection stays read only.', 'Per-run token/cost targets and context thresholds warn using reported telemetry and configured rates. Unknown usage or prices remain unknown. Alerts can lag and do not enforce a billing cap.', 'Support exports redacted diagnostic reports without terminal output, prompt text, environment values, configuration contents, or credentials. Signed Windows builds require your trusted certificate and expected publisher; the manual pipeline verifies signatures and upgrade retention. Ordinary builds are unsigned when no certificate is configured.'] },
  ], related: ['workflow-tools', 'permissions', 'review', 'tokens', 'rules'] },
  { id: 'workflow-tools', category: 'Workflow & troubleshooting', title: 'Diagnostics, resume, experiments, and recovery', summary: 'Use the complete local workflow: task scopes, verification, experiments, and backups.', sections: [
    { title: 'Diagnose and resume', paragraphs: ['Accounts & connections can check installation, login, local configuration syntax, the working folder, and a real native terminal probe. These checks do not send a model request. Provider completion remains unverified until you start a channel and submit a task.', 'Settings shows the renderer and host versions, executable, application folder, and active data folder. New source files do not replace an installed shortcut.', 'Session history → View native CLI conversations discovers default and named-profile conversations. Resume creates an idle channel with the original conversation ID and account. Start it when ready. New-run telemetry excludes old conversation usage. Cloud chat history is not imported.'] },
    { title: 'Prompt experiments', paragraphs: ['AI coaching lets you define an A/B prompt experiment with a hypothesis and success criterion. Link recorded CLI runs and add outcome evidence, elapsed minutes, and rework. Token counts come from local telemetry; time and outcomes are self-reported. Descriptive comparisons do not prove that wording caused an improvement.'] },
    { title: 'Coordinate, verify, and recover', paragraphs: ['Tasks give each agent a job and, if you like, the files it may change. Press Task on a channel (or New task under Tasks), write what to do, and Save and send: Trace types the task into that channel as one message, with its files and a request to list what it changed. The task moves to Working, then to Ready for review when the agent ends its reply with TASK COMPLETE, with the files it changed since it was sent; you mark it done. A reply that ends with TASK BLOCKED, or with neither line, keeps it in Working, and so does a channel that stops or fails (the task is marked, with Send again). Every 30 seconds Trace warns, on the task and under its channel, when an agent changes files outside its task or the same files as another task. Git cannot say who changed a file, so a change counts for a task when it was the only one working in that project. Trace does not stop an agent from changing other files.', 'Verification profiles save explicit tool argument arrays and timeouts. A native confirmation shows the commands and project before execution. Package scripts and hooks run with your local permissions. Results include actual exit codes, bounded output, cancellation, and timeout status.', 'Settings creates SHA-256-verified backups of local workspace data, SQLite history and usage, rules, memory, tasks, experiments, and checks. Logs are optional. Credentials and external repositories are excluded. Restore prepares a separate copy; activate it with an explicit restart. Current data remains intact. Named profiles need login again. Backups are unencrypted: protect exported files.'] },
  ], related: ['permissions', 'review', 'tokens', 'memory', 'rules'] },
  { id: 'ai-coaching', category: 'Agents & models', title: 'AI coaching, prompt wording, and usage trends', summary: 'Review local statistics and explicitly select examples for provider-based advice.', sections: [
    { title: 'Local evidence first', paragraphs: ['AI coaching summarizes CLI-reported usage within a selected time window and provides local heuristic suggestions. Reasoning tokens are not added twice. Estimated costs use configured model prices. Outcomes are self-reported; fewer tokens alone do not prove better results.', 'Add curated prompt wording and outcome notes yourself. The app does not automatically collect full logs, credentials, or environment variables for the report. Select up to five examples and inspect the complete report before sharing. Nothing is sent to a model by opening the screen. Local findings are heuristics, not AI-generated analysis.'] },
    { title: 'Live coaching', paragraphs: ['Trace checks each prompt you send in a Claude Code or Codex channel and shows up to two tips under that channel; the checks run on this computer. Every prompt is also listed under Live coaching on this screen, where you can save it as an example.', 'Ask AI sends that one prompt, and the end of the reply before it, to Claude Haiku through Claude Code, with no tools. It returns advice and a rewrite in a few seconds and uses a little of your Claude plan. Turn live coaching off with Coach my prompts as I send them. Another computer’s channels are coached there, and shown on its tab here and on your phone.'] },
    { title: 'Ask an agent', paragraphs: ['Approve the reviewed report and prepare a Claude or Codex coaching channel. A separate local folder holds the report and your shared rules; your project files are not copied. Choose the account and model, start the idle channel, finish CLI trust/setup prompts, then click Send coaching request. Agent advice appears in the terminal and saved history.', 'The optional agent step uses your CLI provider, not offline inference. Normal CLI tools and approvals apply. The coaching request asks for analysis only, meaning-preserving rewrites, and measurable experiments, without commands or unrelated file access. After an app restart, type Read COACHING_REPORT.md and provide coaching in the coaching channel. Prepared reports and examples are local and are not synced as Drive handoff memory.'] },
  ], related: ['tokens', 'prompting', 'review', 'auth'] },
  { id: 'claude-profiles', category: 'Start here', title: 'Multiple Claude accounts and profiles', summary: 'Connect separate Claude accounts and choose an account for each channel.', sections: [
    { title: 'Connect your accounts', paragraphs: ['Open Accounts & connections and find Claude account profiles. Add a profile name, choose Connect Claude profile, and complete the official browser or terminal login. Select the intended account in your browser; existing browser cookies may preselect another account. Repeat for your other accounts. Default continues to use your existing local CLI login. You can create up to ten named profiles.'] },
    { title: 'Run accounts side by side', paragraphs: ['In a Claude channel, open Settings and select Claude account profile. The CLI login must be verified for that named profile before launch. Start the channel, then assign a different profile to another Claude channel. Up to eight channels can run together. Stop a channel before changing its profile. Reconnecting a profile is blocked while channels use it; other profiles can continue running. Profile names can change without changing saved assignments.'] },
    { title: 'Local isolation and settings', paragraphs: ['Each named profile has its own CLAUDE_CONFIG_DIR under ~/.coding-hub/claude-profiles, with independent login storage, user settings, skills, and user MCP configuration. Claude Code owns credential storage and refresh. Trace stores profile labels and IDs, never copies credentials, and excludes login terminal output from coding history and Drive notes.', 'Named profiles clear inherited Claude authentication environment overrides so a host API key or OAuth token does not silently select the same account. The default sign-in also drops an inherited API key or login token, but keeps CLAUDE_CONFIG_DIR when it is set. Project settings can explicitly provide authentication helpers or environment overrides, so inspect them if an unexpected account appears. Project instructions, shared rules, and project-level integrations still apply. Usage is read from the selected profile’s session logs. Use a current official Claude CLI.'] },
  ], related: ['auth', 'workspace', 'mcp', 'skills', 'memory'] },
  { id: 'overview', category: 'Start here', title: 'How Trace works', summary: 'Understand the app, your local CLIs, and the models behind them.', sections: [
    { title: 'A workspace around your existing tools', paragraphs: ['Trace runs Claude Code and Codex on this computer, each in a channel: a terminal, or a chat that Trace draws (see Chat channels and approvals). Each CLI manages its own account, model connection, tools, and approval prompts. You can run both on the same project or assign separate repository folders.', 'The interface and storage run locally. Model inference usually happens on the provider’s servers, and an MCP server may access an external service. “Local workspace” does not mean the models work without an internet connection.'] },
    { title: 'Your first channel', paragraphs: [], bullets: ['Install and sign in to each official CLI, then confirm its version in the terminal used to launch the app.', 'Open a project. Leave model and reasoning fields blank to inherit the CLI defaults.', 'Start a channel, click its terminal, and explain the task and acceptance criteria.', 'Review the changed files and diff. Run relevant tests before committing.', 'Save a handoff in Shared memory so the next agent knows what happened.'] },
  ], related: ['agents', 'extensions', 'workspace', 'chat', 'shortcuts', 'auth'] },
  { id: 'agents', category: 'Agents & models', title: 'AI, language models, and coding agents', summary: 'A model generates text; an agent combines the model with tools and a workflow.', sections: [
    { title: 'The main terms', paragraphs: ['Artificial intelligence is a broad field of systems that perform tasks such as prediction, recognition, and planning. A large language model (LLM) is trained to generate sequences of tokens. It can produce useful explanations and code, but it can also produce confident errors.', 'A coding agent adds a loop around a model: read the task, inspect files, choose an action, call a tool, inspect the result, and continue. Claude Code and Codex provide this agent loop. A shell command, file edit, or MCP request is an action the surrounding software executes.'] },
    { title: 'Two perspectives', paragraphs: ['Running two agents can help compare approaches or split independent work. They do not automatically share conversation context. When both edit the same files, they can undo each other’s changes or create conflicts. Assign clear ownership or use separate repositories/worktrees that you create through your normal Git workflow.'] },
  ], related: ['models', 'prompting', 'review', 'memory'] },
  { id: 'models', category: 'Agents & models', title: 'Models, reasoning, and thinking budgets', summary: 'Choose a model and understand the raw engine-specific controls.', sections: [
    { title: 'Model selection', paragraphs: ['The model is the underlying system generating the response. Capability, speed, context size, price, and supported parameters vary by model. A model name listed in the app is an editable suggestion, not proof that your account can use it. Leave the field blank for the CLI’s configured default.'] },
    { title: 'Claude controls', paragraphs: ['The model field maps to --model. Manual thinking.budget_tokens maps to MAX_THINKING_TOKENS for supported explicit manual-thinking models. It must be at least 1,024 tokens and smaller than a specified output limit. Adaptive-thinking models and aliases may not support a manual budget.', 'Maximum output tokens limits a response through the CLI’s supported environment setting. The channel’s token threshold stops the process after reported usage reaches the threshold. A response can exceed it, and missing usage prevents reliable enforcement. It is not a hard billing cap.'] },
    { title: 'Codex controls', paragraphs: ['Codex settings query the installed CLI for its full model catalog, including additional models and all returned pages. Model suggestions use exact CLI model values. You can also enter a custom ID or leave the field blank for your configured default. A catalog entry does not prove account access or billing.', 'Reasoning effort maps to model_reasoning_effort. Selecting a catalog model shows its reported reasoning levels; incompatible prior overrides reset to CLI default with a notice. Explicit raw settings still require support from your installed CLI and selected model. More effort may improve difficult work, but can increase latency and token use; it does not guarantee correctness.'] },
  ], related: ['tokens', 'usage', 'auth'] },
  { id: 'retrieval', category: 'Agents & models', title: 'Retrieval, embeddings, and RAG', summary: 'How an AI system finds relevant information before answering.', sections: [
    { title: 'Retrieval adds evidence to the request', paragraphs: ['Retrieval means searching for relevant information and supplying it to the model. RAG stands for retrieval-augmented generation: retrieve useful material, then generate an answer using that material. A coding agent may use ordinary file search, a documentation tool, or an MCP server as part of retrieval.', 'An embedding is a numerical representation used to compare meaning or other learned characteristics. A vector search can use embeddings to find similar passages. Retrieval can also use exact keywords, paths, or database filters; not every search needs embeddings.'] },
    { title: 'Useful context still needs checking', paragraphs: ['Documents may be split into smaller chunks for search. Finding a relevant-looking chunk does not prove it is current, accurate, or complete. Ask for the source path, check surrounding code, and verify claims against the actual project.', 'Retrieval does not train the model or grant permission to access a source. Retrieved material uses context space and can contain untrusted instructions. Trace does not automatically build an embedding database; its shared-memory server returns curated project handoffs.'] },
  ], related: ['tokens', 'memory', 'mcp', 'permissions'] },
  { id: 'training', category: 'Agents & models', title: 'Training, fine-tuning, and instructions', summary: 'Understand what changes a model and what simply guides a session.', sections: [
    { title: 'Training changes learned parameters', paragraphs: ['Pretraining teaches a model patterns from a large dataset. Further training can adapt behavior; fine-tuning is one way to update learned parameters using selected examples. These are separate activities from asking a model to perform a task.', 'A prompt, CLAUDE.md, AGENTS.md, skill, or handoff supplies information and instructions for a session. Writing those files does not update the provider model’s weights. A model can appear to learn your preferences within a conversation because they remain in its context.'] },
    { title: 'Choose the simplest useful mechanism', paragraphs: ['Use rules for persistent expectations, skills for reusable procedures, and retrieval or memory for current project knowledge. Fine-tuning can be appropriate for specialized repeated behavior, but needs suitable data, evaluation, and provider support; it does not guarantee factual knowledge stays current.', 'Trace runs your installed CLIs and does not train or fine-tune models. Provider account settings govern data handling for model requests; local app storage alone does not determine a provider’s retention or training policy.'] },
  ], related: ['models', 'rules', 'skills', 'retrieval'] },
  { id: 'tokens', category: 'Agents & models', title: 'Tokens, context windows, and compaction', summary: 'Why a long conversation uses space and why an agent can lose details.', sections: [
    { title: 'Tokens are pieces of text', paragraphs: ['A token can be a word, part of a word, punctuation, or another encoded unit. Token counts are not the same as character or line counts. Prompts, instructions, file excerpts, tool results, and answers can all contribute to usage.', 'Input tokens are text supplied to the model; output tokens are generated text. Cached input may reuse earlier context at a different price. Some reasoning tokens are already included in output counts, so adding them again would overstate usage.'] },
    { title: 'Context is a working window', paragraphs: ['A context window is the amount of information a model can consider in a request. It is not permanent memory. Large file dumps and long tool output can crowd out useful details. Agents may compact a conversation into a summary to keep working; summaries can omit details.', 'Keep important project rules in instruction files and decisions in curated handoffs. Ask the agent to re-read the relevant source when exact details matter. Trace shows context percentage only when the CLI reports both usage and a window limit.'] },
  ], related: ['memory', 'rules', 'usage'] },
  { id: 'extensions', category: 'Tools & extensions', title: 'MCPs, skills, plugins, rules: the differences', summary: 'Pick the right mechanism for access, procedures, packaging, or expectations.', sections: [
    { title: 'Different roles', paragraphs: ['An MCP server exposes tools or data using a shared protocol. A skill describes a procedure the agent can use. A plugin packages extensions for an engine. Rules state your persistent expectations. Memory records project facts and progress.', 'They can work together: a plugin can bundle a skill that tells the agent how to use an MCP tool, while your rules require tests before a handoff is saved. None of these changes the underlying model’s training.'] },
    { title: 'A practical example', paragraphs: [], bullets: ['MCP: access issue records from a project tracker.', 'Skill: follow the team’s review procedure when inspecting a pull request.', 'Plugin: install the tracker integration and review skill together.', 'Rules: preserve public APIs and run the relevant tests.', 'Memory: record the review findings and unresolved questions.'] },
  ], related: ['mcp', 'skills', 'plugins', 'rules', 'memory'] },
  { id: 'mcp', category: 'Tools & extensions', title: 'Model Context Protocol (MCP)', summary: 'A standard way for an agent to discover and call tools or read resources.', sections: [
    { title: 'Client and server', paragraphs: ['MCP stands for Model Context Protocol. The CLI acts as an MCP client. A server describes the capabilities it offers and handles requests. Tools perform actions; resources provide data; prompts can provide reusable task templates. Not every server supports all three.', 'An MCP server is not another model by default. It might read local files, query a database, access an issue tracker, or write a handoff. An action that writes to an external service has the consequences of that service action.'] },
    { title: 'Transports and configuration', paragraphs: ['A stdio server runs as a child process and exchanges messages through standard input/output. HTTP connects to a server URL. SSE is an older transport you may encounter in existing configurations.', 'In MCP servers, select a project to inspect its files, add a command with an argument array or an HTTP URL, and supply inherited environment-variable names when needed. Existing credential values remain private. “Enabled” means configured, not that a health check or login has succeeded. Restart channels after changing configuration.'] },
    { title: 'Trust and authentication', paragraphs: ['Install servers from sources you trust and understand the permissions they require. Stdio commands run on your machine; remote servers can access the data you send them. A server’s authentication is separate from your Claude/Codex account login. The CLI can require project trust, a tool approval, or a service login.'] },
  ], related: ['permissions', 'auth', 'memory', 'mcp-errors'] },
  { id: 'skills', category: 'Tools & extensions', title: 'Skills and SKILL.md', summary: 'Reusable instructions for doing a particular kind of work.', sections: [
    { title: 'A procedure, not a new model', paragraphs: ['A skill usually has a SKILL.md file describing when and how to perform a task. It may also include templates, reference documents, and scripts. Examples include reviewing a change, creating a report, or following a release checklist.', 'The CLI decides how skills are discovered and activated. Activation may be explicit or based on the task. A skill that invokes a script or external tool can still require permissions. Reading instructions alone does not prove the requested workflow was followed.'] },
    { title: 'Inspecting skills in this app', paragraphs: ['Skills & plugins shows instructions found in local project/user folders, including supported Codex system-skill folders. Select a skill to inspect its content and source. Supported Codex skill activation can be toggled. Claude skills are inspected in place; use the CLI’s supported workflow to manage their installation.', 'Skills differ from shared rules: rules describe expectations for all relevant work; a skill describes a particular procedure.'] },
  ], related: ['plugins', 'rules', 'permissions'] },
  { id: 'plugins', category: 'Tools & extensions', title: 'Plugins and marketplaces', summary: 'Packages that group capabilities for a particular CLI.', sections: [
    { title: 'What a plugin can contain', paragraphs: ['A plugin can package skills, commands, hooks, MCP servers, or other engine-supported extensions. A marketplace is a catalog or distribution source for those packages. Formats and activation behavior differ between Claude Code and Codex.', 'A plugin is not the same thing as an MCP server, and a plugin installed for one CLI is not automatically available to the other. Its bundled tools still use their normal authentication and permission controls.'] },
    { title: 'Local management', paragraphs: ['Trace inspects installed metadata, bounded cache manifests, and configured activation. It can toggle supported configured plugins, preserving other settings. It does not automatically install marketplace packages or run plugin scripts during discovery. Use the engine’s installation workflow, then refresh the app and restart channels.'] },
  ], related: ['mcp', 'skills', 'hooks'] },
  { id: 'hooks', category: 'Tools & extensions', title: 'Hooks, shell commands, and approvals', summary: 'Event-triggered automation is different from model-generated instructions.', sections: [
    { title: 'Hooks run at defined events', paragraphs: ['A hook is a configured command or action triggered at an event such as session start, a tool call, or session completion. An engine may support allowing, blocking, or modifying an operation through a hook; exact behavior is version-specific.', 'A shell command is a program execution in the agent’s working folder. An agent may propose one as a tool action; a hook can execute one because an event occurred. Both can modify files or contact services. Trace lists hook event names without executing hook commands.'] },
    { title: 'Instructions versus enforcement', paragraphs: ['Writing “run tests” in Shared rules guides the agent. An approved hook or CI check can actually enforce a test condition. Do not assume a sentence in an instruction file disables a tool, prevents a write, or creates an operating-system sandbox. CLI permission controls and repository checks serve those roles.'] },
  ], related: ['rules', 'permissions', 'review'] },
  { id: 'rules', category: 'Rules & memory', title: 'Shared rules for both engines', summary: 'Write one set of expectations and apply it to both project instruction files.', sections: [
    { title: 'One editor, matching instructions', paragraphs: ['Shared rules saves one rule document locally. Choose the project folders that should receive it; this includes the workspace root and the folders of channels that have their own. Apply writes the identical managed section to CLAUDE.md for Claude Code and AGENTS.md for Codex.', 'Existing instructions and the separate shared-memory section are preserved. Backups are created, and edits are rejected if the files changed after inspection. Reapplying replaces the managed section rather than duplicating it. Clearing the editor and saving removes only that section from selected projects.'] },
    { title: 'When rules take effect', paragraphs: ['Restart channels after applying changes. When nonempty shared rules are saved, Trace checks that both instruction files contain the current version before it starts a channel in that folder. If a project has not received them, apply rules there first.', 'These are instructions to the agents, not a guarantee that every generated action follows them. Engine instructions, permission controls, and more specific project instructions still affect behavior. Resolve contradictions and verify results. Use tests, hooks, or CI for requirements that need mechanical enforcement.'] },
    { title: 'A useful starting point', paragraphs: ['Prefer concrete, testable expectations over vague demands. Keep rules short enough that the important constraints stand out.'], example: 'Preserve public APIs unless I explicitly request a breaking change.\nInspect existing code before adding a dependency.\nRun relevant tests after meaningful changes; report checks you could not run.\nDo not commit, push, deploy, or modify credentials unless I ask.\nBefore finishing, save a handoff with decisions, changed files, validation, and remaining work.' },
  ], related: ['instructions', 'hooks', 'memory', 'review'] },
  { id: 'instructions', category: 'Rules & memory', title: 'CLAUDE.md, AGENTS.md, and instruction scope', summary: 'Understand how project instructions differ from a chat prompt.', sections: [
    { title: 'Persistent project instructions', paragraphs: ['CLAUDE.md and AGENTS.md are Markdown instruction files consumed by their respective coding tools. They can describe conventions, commands, architecture, and constraints. User-level and project-level instructions can both exist; an engine may also read nested or local-only files.', 'The active working folder and the engine’s discovery rules determine which files apply. A nested instruction file can add more specific requirements. Shared rules preserves existing text, so conflicting older instructions may still need manual review.'] },
    { title: 'What to store where', paragraphs: [], bullets: ['Rules: stable expectations such as test commands and approval boundaries.', 'Chat prompt: the current task and its acceptance criteria.', 'Skill: a reusable procedure for a category of tasks.', 'Handoff memory: decisions, progress, validation, and next steps.'] },
  ], related: ['rules', 'prompting', 'memory'] },
  { id: 'memory', category: 'Rules & memory', title: 'Shared memory and Google Drive', summary: 'Carry useful project knowledge across conversations without copying entire transcripts.', sections: [
    { title: 'Curated handoffs', paragraphs: ['Conversation context is temporary. Shared memory stores concise notes about decisions, changed files, tests, remaining work, and blockers. Every Claude Code and Codex channel started in Trace gets the project’s recent notes and the memory tools at launch, with no change to project files: read_memory, write_handoff, list_open_items, resolve_open_item, list_decisions and retire_decision. Install memory from Shared memory only for CLIs you run outside Trace; then restart them and approve the server through the CLI.', 'Reading a handoff does not import the other agent’s hidden reasoning or entire conversation. Notes can become outdated, so verify important facts against the current repository. Rules describe expectations; memory records what happened.'] },
    { title: 'Drive synchronization', paragraphs: ['Google Drive for desktop handles cloud transport for the local folder chosen in Settings. On Windows it starts as G:\\My Drive\\Coding Hub. A Mac has no default folder, so choose one there. The app mirrors curated notes into AI-Coding-Hub-Memory/<project-key>. Use the same project key across desktops and different keys for unrelated projects.', 'Local notes remain available offline. Sync retries while the app is open for projects you have opened. Starting a channel waits up to 1.5 seconds for its project’s sync, so a note written on another computer moments before is usually in its starting context. Sync now reports the folder mirror result; check Google Drive’s own status for cloud upload completion. Databases, credentials, and raw terminal logs do not sync. Conflicting IDs preserve both versions for review.'] },
  ], related: ['mcp', 'rules', 'drive-errors'] },
  { id: 'prompting', category: 'Daily workflow', title: 'Give an agent a clear task', summary: 'Specify the outcome, constraints, and evidence you expect.', sections: [
    { title: 'A useful task description', paragraphs: ['Describe the problem, what should change, what must be preserved, and how success can be checked. Supply the relevant file paths and observed error messages. Ask the agent to inspect the current implementation before assuming how it works.', 'For a larger task, ask for a plan and concrete acceptance criteria. For two simultaneous agents, assign independent work or make one review the other’s changes. Avoid having both rewrite the same files without coordination.'], example: 'Fix the login redirect loop in this repository. Preserve the existing authentication API. Inspect the current flow, reproduce the failure, make the smallest justified fix, and run the relevant tests. Report the cause, changed files, and any unverified behavior.' },
    { title: 'Keep the conversation useful', paragraphs: ['If the agent goes off track, state the correction directly. Ask it to distinguish facts from assumptions and executed tests from suggested tests. Provide the final error lines rather than a huge unfiltered log. Save a handoff before switching agents or ending a long conversation.'] },
  ], related: ['review', 'agents', 'memory'] },
  { id: 'workspace', category: 'Daily workflow', title: 'Channels, folders, and the terminal grid', summary: 'Control what runs, where it runs, and how channels are laid out.', sections: [
    { title: 'Choose or create a project', paragraphs: ['Projects opens an existing folder, accepts an absolute folder path, creates a new project folder, or lists and clones GitHub repositories through GitHub CLI. Account login is independent of project selection.', 'The native folder picker shows folders rather than code files. You can select the current folder with Use this folder even if its displayed file list is empty. For a channel with its own folder, choose Independent repository under Working folder in its settings, then Choose folder. Existing local folders are never overwritten by creation or cloning.'] },
    { title: 'Working folders matter', paragraphs: ['The working folder (cwd) determines the files, Git context, and project instructions the CLI sees. Channels use the workspace root by default; an independent folder lets a channel work on another repository. Point at a channel’s header to see the folder it runs in; the status bar names the project.', 'Run one to eight channels. Drag headers to reorder, resize a corner, choose rows/columns/grid, or isolate a channel. In the grid, a last row with fewer channels shares the whole width: three channels are two above and one wide below. Switching pages retains terminal instances and scrollback.'] },
    { title: 'Lifecycle controls', paragraphs: ['Start launches a local CLI. Interrupt sends Ctrl+C for the current operation. Stop terminates the CLI and its owned child process tree; Windows uses force termination of that tree. The terminal is disabled after confirmed exit, and prior output remains recorded. If stopping fails, the app reports the error and keeps the channel’s PID available for troubleshooting. Start and Restart launch a new process that continues the channel’s recorded conversation; choose Start a fresh conversation next time (in the channel’s Settings) to begin a new one instead.', 'Closing or reloading stops the owned PTYs. Saved layouts and settings restore as idle channels, which continue their conversations when started, and past output appears in Session history. A detached background job may have its own lifetime. Ctrl+Shift+P opens the command menu; on macOS use Cmd+Shift+P.'] },
  ], related: ['instructions', 'review', 'installation'] },
  { id: 'review', category: 'Daily workflow', title: 'Review code, tests, and Git changes', summary: 'Use evidence before trusting a confident answer.', sections: [
    { title: 'AI can be wrong', paragraphs: ['A hallucination is an unsupported or incorrect generated claim. An agent can invent a function, misread a test result, or claim a task is complete without executing a check. Confidence and polished prose are not validation.', 'Review the diff for unintended edits, inspect the actual code, and run relevant checks. Ask for precise results: which commands ran, what passed, what failed, and what remains unverified.'] },
    { title: 'Use the app’s review tools', paragraphs: ['Show explorer keeps files beside the terminals. Files gives a larger read-only preview. Changes groups staged, unstaged, and untracked files and shows colored Git diffs. Select the workspace or a channel’s repository, then refresh after edits.', 'Beside the diff, Delivery stages, commits, pushes and opens a pull request, each after a confirmation; there is no discard or force push. Check binary changes and conflicts separately; large previews are explicitly bounded. Keep a known-good commit before substantial agent work.'] },
  ], related: ['permissions', 'prompting', 'rules'] },
  { id: 'usage', category: 'Daily workflow', title: 'Usage, cache counts, and cost estimates', summary: 'Read the dashboard without confusing estimates with billing.', sections: [
    { title: 'Reported usage', paragraphs: ['Trace reads supported structured CLI session logs and deduplicates repeated usage events. Counters appear after the CLI reports a response. A dash means unknown, not zero. Unsupported CLI versions, disabled transcript logging, or ambiguous thread association can prevent counts.', 'Claude cache reads/writes are separate from its noncached input. Codex cached input is included in input and reasoning is included in output. Context percentage is available only when the CLI supplies a usage/window pair.'] },
    { title: 'Prices and daily history', paragraphs: ['Trace prices Claude, GPT and Gemini models itself from Anthropic’s, OpenAI’s and Google’s published prices, so nothing needs to be entered. To use your own rate for a model, add it in Settings (USD per million tokens, by the model’s name or ID); it also prices the same model logged with a release date (claude-x-20261101). A model nobody lists a price for shows no cost estimate. Estimates use the standard price for every request (a prompt long enough for a provider’s long-context price is not told apart) and exclude account discounts and billing adjustments; consult the provider for actual charges. Gemini CLI’s tokens are read from its own conversation files and count by day (today’s total and the Usage screen); a Gemini channel’s tile shows no count of its own. On a subscription Gemini CLI is not billed by the token: its cost is what the same use would cost through the API.', 'Tokens count on the local day they were used, so a run that crosses midnight counts on both days. Usage shows Today or the last 7, 14 or 30 days, from the latest 2,000 runs in up to one year of retained usage. The cost total adds up the priced runs and says how many are unpriced.'] },
  ], related: ['tokens', 'models', 'telemetry-errors'] },
  { id: 'chat', category: 'Daily workflow', title: 'Chat channels and approvals', summary: 'An agent as a conversation: formatted replies, images inline, and approvals as buttons.', sections: [
    { title: 'A conversation instead of a terminal', paragraphs: ['A chat channel runs Claude Code or Codex without its terminal screen, and Trace draws the conversation: your messages with images, formatted replies, tool calls as cards with their results, and Claude’s thinking folded away. It uses the channel’s folder, account, model, shared rules and shared memory, and its usage is recorded as a terminal’s is. A chat comes with a Round Table, with Start in worktree on a task, or from a linked computer.', 'Paste, drop or attach up to ten images per message. Stop interrupts the reply; a restarted chat continues the conversation. Screens that only exist in the terminal, such as /config, need a terminal channel.'] },
    { title: 'Approvals', paragraphs: ['When the agent asks to use a tool its Permissions level does not already allow, a card offers Allow, Deny, and for Claude Allow edits this run when it suggests it (Codex: Allow for this session). The channel shows as waiting on its tile, in the status bar and on a paired phone until you answer, and in a notice while its tile is not on screen.'] },
  ], related: ['round-table', 'permissions', 'phone'] },
  { id: 'round-table', category: 'Daily workflow', title: 'Round Table: several agents in one channel', summary: 'Claude Code and Codex agents discuss, build and review together, in one tile, in seats you set up.', sections: [
    { title: 'Seats and presets', paragraphs: ['+ Channel → Round Table or Round Table (hierarchy), or the people button beside a chat’s message box, opens the setup panel. Pick a table from the list, change a copy of it, and press Start. Trace comes with two tables, a discussion of Claude Code and Codex and a planner, builder and reviewer hierarchy; Save as preset keeps your own, and Update preset and Delete preset change or remove one of yours (never the two built in). From a chat, the table sits at that chat’s own agent and model.', 'Each seat is an agent of its own, Claude Code or Codex, with its own model (blank is the CLI’s default), a name (the seat is labelled with it in the thread) and instructions for what it should focus on. A table has at least 2 seats and at most 8. Every seat is a CLI on your own login and plan, and counts toward the eight agents and terminals Trace runs at once, so the panel says how many more seats fit.', 'The Seats button on a table’s bar opens the same panel for the table that is open: add or remove seats, rename them, change instructions, duties, models, the agent that edits and the rounds. It works while the table is not working; Trace says so if you try during a turn. Changing a seat’s model restarts that agent, and its conversation is resumed. The channel that leads the table cannot be removed.'] },
    { title: 'A discussion table', paragraphs: ['Each message goes to every seat to discuss first: nobody changes files yet. Each then sees the others’ answers and replies, for up to the chosen number of rounds, or until all answer AGREE. Then the driver makes the changes, going by the whole discussion. Exactly one seat, the driver, edits files, and only in that last turn; the others are read-only reviewers, and Trace declines their edits. With Rounds at 0 the driver starts at once, without a discussion. With two seats Swap changes roles; with more, choose the seat that edits from the list. Stop ends every agent’s turn; Close ends the table.', 'A reviewer reports problems as FINDING high|medium|low path:line — problem lines. Trace numbers them F1, F2, …; the driver answers FIXED or DECLINED, and a reviewer checks with VERIFIED or REOPENED. The record comes back after a restart, and closing the table saves it to shared memory, with each finding not yet verified as an open item. A line Trace cannot read is named in a notice.'] },
    { title: 'A hierarchy table', paragraphs: ['In a hierarchy each seat has duties: plan, challenge, build, review and final review. Exactly one seat builds, and it leads the table: it is the only seat that edits files, and it only builds. Exactly one seat plans. Any number of seats challenge the plan or review the builder’s changes, and at most one gives the final review; a table can have no challengers, no reviewers or no final reviewer, and the bar then leaves those steps out. The built-in table is a Claude builder, a Claude planner who also gives the final review, and a Codex reviewer who also challenges the plan.', 'The planner plans, the challengers challenge the plan, you approve it, the builder builds, the reviewers review, the builder fixes, and the final reviewer approves or asks for changes. Several challengers or reviewers take their step one after another, and the bar says whose turn it is. Without a final reviewer a task is done when the review rounds end; the review rounds (1 to 5) are set in the bar or the panel. Stop halts the seat at work; Continue runs its step again.'] },
    { title: 'On a phone and other computers', paragraphs: ['A paired phone and a linked computer show every seat in one thread, answer approvals from any of them, and can stop, set the rounds and close a table. They start only the two built-in tables, and have no Seats button: change seats on this computer.'] },
  ], related: ['chat', 'review', 'memory', 'permissions'] },
  { id: 'phone', category: 'Daily workflow', title: 'Phone access', summary: 'Read, type into and answer your channels from your phone, over your own Tailscale network.', sections: [
    { title: 'Set it up', paragraphs: ['Phone access is off until you turn it on in Settings → Phone access. Install Tailscale on this computer and your phone, signed in to the same account; Trace asks before it sets up Tailscale HTTPS, and shows the steps if your tailnet needs certificates turned on. Pair a phone by scanning the QR code, or open the address shown and type the code: a code works once, for five minutes.', 'Add the page to your home screen so it opens like an app. Turn on alerts there to be told when a channel needs you or stops with an error, even with Trace closed.'] },
    { title: 'What a phone can do', paragraphs: ['A paired phone sees every channel, types into running ones, answers approvals and uses chats and Round Tables. It shows usage, tasks, Session history and memory, and the computer’s screen. Starting, stopping and adding channels needs Can start and stop agents, which is off for each phone until you turn it on. A terminal channel you open on the phone is redrawn at the phone’s size until you type in it here, leave it on the phone or lock the phone; press Desktop size on the phone to keep this computer’s size instead. Treat a paired phone like an unlocked keyboard on this computer, and remove phones you no longer use.'] },
  ], related: ['other-computers', 'chat', 'permissions'] },
  { id: 'other-computers', category: 'Daily workflow', title: 'Other computers', summary: 'See and control the channels on your other computers running Trace.', sections: [
    { title: 'Linking', paragraphs: ['With sync between computers on, each computer lists the others under Settings → Other computers. With Link my computers automatically on (the default), computers signed in to the same Tailscale account link without a code, and Trace tells you each time one does; remove one you do not recognise there. Otherwise Show link code on the computer to be reached gives a code for the other to enter.', 'Each linked computer gets a tab. There you follow its channels, type and paste into them, add, start, stop, restart or close them (that computer’s window carries the request out), read a channel’s whole conversation, and open its screen. Its channels that need you are counted on the tab, and raise a notification while Trace is not in front.'] },
  ], related: ['phone', 'memory', 'workspace'] },
  { id: 'plan-limits', category: 'Daily workflow', title: 'Plan limits and daily budgets', summary: 'How much of your subscription limits and your own daily budget is used.', sections: [
    { title: 'Plan limits', paragraphs: ['The status bar shows how much of Claude’s session and weekly limits, and Codex’s limits, each account has used: amber from 75%, red from 90%. Point at it for every limit and its reset time; Usage has a Plan limits card with Check now. Trace reads them from each CLI without a model request when it opens, every five minutes, and when you return to the window. Accounts billed by API usage have no limit to show.'] },
    { title: 'Daily budgets and warnings', paragraphs: ['Settings → Alerts and daily budget sets a daily token budget and a daily cost budget for this computer, and the share to warn at (80% unless you change it). Trace warns once at that share and once when a budget is used up, and the same way, once per window, for each plan limit. A warning is a notification; nothing is stopped.'] },
  ], related: ['usage', 'tokens', 'telemetry-errors'] },
  { id: 'shortcuts', category: 'Start here', title: 'Keyboard shortcuts', summary: 'Move between channels and views without the mouse.', sections: [
    { title: 'Keys', paragraphs: [], bullets: ['Alt+1 to 8 (Cmd+1 to 8 on a Mac): focus a channel.', 'F1: open this guide.', 'Ctrl+Shift+P (Cmd+Shift+P): the command menu, for actions, channels, files and memory notes.', 'Ctrl+Shift+F (Cmd+Shift+F): search project files, notes and rules.', 'G, then a letter: W Workspace, C Changes, P Projects, U Usage, H History, F Files, T Tasks, V Verification, O Coaching, L More tools, A Accounts, M Memory, R Rules, S Settings.', 'Enter on a focused idle channel starts it. Keys typed in a terminal go to the CLI.'] },
  ], related: ['workspace', 'overview'] },
  { id: 'permissions', category: 'Tools & extensions', title: 'Permissions, trust, and prompt injection', summary: 'Understand what an agent can access and what an instruction cannot enforce.', sections: [
    { title: 'Keep authority explicit', paragraphs: ['Each Claude Code and Codex channel has a Permissions setting, in its Settings and, for a chat, beside the message box. Ask keeps the CLI’s own approval settings. Allow edits, the default, lets the agent edit files without asking (Claude still asks before other commands; Codex also runs commands inside the project). Full access never asks: any command, any file. Trace passes the level as launch flags, so a terminal channel takes a change when it next starts; a chat takes it at once (a Codex chat from its next message). At a Round Table one setting covers every seat.', 'CLI approval prompts control the actions a level leaves to them. An instruction such as “ask before pushing” is useful guidance, while an enforced permission restriction prevents the action mechanically.', 'Treat repository text, external documents, tool output, and handoffs as potentially untrusted data. Prompt injection happens when such content tries to redirect the agent’s behavior or obtain information it should not receive. A document being retrieved by a tool does not make its instructions authoritative.'] },
    { title: 'Practical habits', paragraphs: [], bullets: ['Keep credentials in the CLI or service’s supported authentication storage, not rules or shared notes.', 'Understand an MCP server or plugin before granting it access.', 'Review proposed destructive commands and external writes.', 'Use tests, branch protections, and CI for conditions that must be enforced.'] },
  ], related: ['mcp', 'hooks', 'rules', 'auth'] },
  { id: 'auth', category: 'Troubleshooting', title: 'Accounts, authentication, and model access', summary: 'Connect Claude Code, Codex, and GitHub using their official CLI login flows.', sections: [
    { title: 'Connect before opening a project', paragraphs: ['Open Accounts & connections from the Agent setup menu in the top bar (or press G, then A). Install missing official CLIs using their installation guides, then refresh. Connect opens an interactive terminal for the tool’s own login workflow; it can open your browser or display a sign-in code. No workspace or shared rules are required to log in.', 'Login output is temporary and excluded from saved coding logs and shared memory. Credentials remain in each CLI’s supported local storage. GitHub CLI supplies GitHub login and repository listing; it does not automatically publish code. Existing CLI sign-ins are detected when status can be verified.'] },
    { title: 'Separate sign-ins', paragraphs: ['Claude Code and Codex each use their own provider authentication and account access. Sign in using the official CLI’s current login workflow. A subscription, API billing account, and enterprise account can provide different model access and limits.', 'An MCP integration may require a separate service token or OAuth login. Installing Google Drive or a chat connector does not sign you into either model provider. The Drive folder integration uses your desktop Drive installation.'] },
    { title: 'If access fails', paragraphs: ['Run the affected CLI in the same system terminal used to launch Trace. Resolve its login or account error there, confirm that the model is available, and restart the app after PATH changes. Leave model settings blank to use the CLI default if a suggested model ID is unavailable. Do not paste credentials into a support conversation.'] },
  ], related: ['installation', 'models', 'mcp-errors'] },
  { id: 'installation', category: 'Troubleshooting', title: 'Windows setup and npm messages', summary: 'Install the source and distinguish warnings from failures.', sections: [
    { title: 'Launch from the project folder', paragraphs: ['Use Node.js 24 LTS, Git, and installed/authenticated official CLIs. Open PowerShell in the extracted folder containing package.json. npm.cmd avoids a blocked npm.ps1 execution-policy wrapper without changing system policy.'], example: 'npm.cmd ci\nnpm.cmd run dev' },
    { title: 'Warnings and errors', paragraphs: ['Deprecated dependency messages are warnings, not proof that installation failed. Let installation finish and inspect the final result. If npm reports an error, use the final error lines to identify the failing package or prerequisite.', 'A missing CLI should be checked with claude --version or codex --version in the launching terminal. Restart after installation/PATH changes. Native PTY rebuilds may require platform build tools; consult the source README for prerequisites. Browser preview cannot start local processes.'] },
  ], related: ['auth', 'workspace'] },
  { id: 'mcp-errors', category: 'Troubleshooting', title: 'An MCP server is enabled but unavailable', summary: 'Check executable, arguments, environment, service login, and project trust.', sections: [
    { title: 'Work through the layers', paragraphs: [], bullets: ['Confirm the executable exists and the argument array matches the server’s documented launch command.', 'Confirm required environment-variable names are available to the CLI process.', 'For remote servers, check the URL, network access, and service authentication.', 'Approve project trust and MCP/tool permissions in the CLI where required.', 'Restart channels after changing config; an app toggle does not reconnect a running channel.'] },
    { title: 'Preserved configuration', paragraphs: ['If configuration changed since inspection, refresh before editing. Malformed JSON/TOML is preserved rather than overwritten. Backups are created for app edits. Claude enablement is project scoped; choose a project before toggling user servers. A legacy ~/.claude/mcp.json may not be used by current Claude Code.'] },
  ], related: ['mcp', 'auth', 'permissions'] },
  { id: 'drive-errors', category: 'Troubleshooting', title: 'Shared notes are not appearing on another desktop', summary: 'Check both the local folder mirror and Google Drive’s upload status.', sections: [
    { title: 'Check the path and project key', paragraphs: ['Open Google Drive for desktop and confirm the selected local folder is available. Its drive letter may differ from G: on another machine. Update Settings to the actual folder, save preferences, and choose Sync now.', 'Both desktops must use the same shared project key and shared Drive folder. A successful app folder sync does not prove Google finished uploading. Check Drive’s status and confirm that the note files appear in AI-Coding-Hub-Memory/<project-key>.'] },
    { title: 'Offline and conflicts', paragraphs: ['Local notes stay available offline and sync can be retried later. Conflicting note IDs are not overwritten. Review both versions and preserve useful information in a new handoff. Do not edit immutable note files as a way to change a handoff; write a new note instead.'] },
  ], related: ['memory', 'mcp'] },
  { id: 'telemetry-errors', category: 'Troubleshooting', title: 'Tokens, context, or cost show a dash', summary: 'Unknown fields stay unknown until the CLI provides usable evidence.', sections: [
    { title: 'Tokens and context', paragraphs: ['Complete a response and refresh Usage. The installed CLI must write a supported structured session log. Claude needs advertised session-ID support for reliable correlation. Multiple Codex channels in the same folder require an identifiable thread association; the app does not guess.', 'Context requires both a used-token count and a context-window limit. A missing context percentage or reasoning count can be normal even when input/output tokens are available.'] },
    { title: 'Cost', paragraphs: ['Add a price row for the exact model ID reported by the CLI, including input/output/cache rates in USD per million tokens, and save preferences. A selected alias may resolve to a different actual model ID. Unconfigured models remain unpriced. A total adds up the priced runs and says how many are unpriced; with none priced, it shows a dash.'] },
  ], related: ['usage', 'models', 'tokens'] },
];

export function searchHelp(query: string, category = 'All topics'): HelpTopic[] {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  // Search visible text only; JSON keys such as "title" or related IDs would otherwise match every topic.
  const text = (topic: HelpTopic) => [topic.title, topic.summary, topic.category, ...topic.sections.flatMap((section) => [section.title, ...section.paragraphs, ...(section.bullets ?? []), section.example ?? ''])].join('\n').toLowerCase();
  return HELP_TOPICS.filter((topic) => (category === 'All topics' || topic.category === category) && words.every((word) => text(topic).includes(word)));
}
